	}
	var actualTasks []Task
	err := json.Unmarshal([]byte(output), &actualTasks)
	if err != nil {
		t.Fatalf("Failed to unmarshal output: %v, output: %s", err, output)
	}

	if len(actualTasks) != len(expectedTasks) {
