func TestTaxCalculator_CalculateTax(t *testing.T) {
	tests := []struct {
		name string
		income float64
		wantTax float64
	}{
		{
			name:    "Zero income",
			income:  0,
			wantTax: 0,
		},
		{
			name:    "Income within 0% bracket",
			income:  5000,
			wantTax: 0,
		},
		{
